import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via cached loader
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Tessellated plane geometry for parallax displacement
  const geometry = new THREE.PlaneGeometry(2, 1.25, 64, 64);

  // Main displaced surface with machined-metal PBR
  const material = new THREE.MeshStandardMaterial({
    map: imageTexture,
    displacementMap: depthTexture,
    displacementScale: 0.05,
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.15,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Focus state edge indicator with accent color
  const edges = new THREE.EdgesGeometry(geometry);
  const edgeMaterial = new THREE.LineBasicMaterial({
    color: 0xff2a38, // accent red
    transparent: true,
    opacity: 0,
  });
  const edgeLines = new THREE.LineSegments(edges, edgeMaterial);
  edgeLines.position.z = 0.001;
  group.add(edgeLines);

  // Scene placement
  group.position.set(-1.25, 1.6, 0);
  const originalY = group.position.y;

  // Hover: rise-in effect (subtle, 0.15 scene units)
  const onHoverEnter = () => {
    gsap.to(group.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverExit = () => {
    gsap.to(group.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Focus: show accent edge
  const onFocus = () => {
    gsap.to(edgeMaterial, {
      opacity: 1,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  const onBlur = () => {
    gsap.to(edgeMaterial, {
      opacity: 0,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  // Click: press-down effect (scale to 0.97)
  const onPointerDown = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  const onPointerUp = () => {
    gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  // Attach event handlers
  group.userData.handlers = {
    onHoverEnter,
    onHoverExit,
    onFocus,
    onBlur,
    onPointerDown,
    onPointerUp,
  };

  // Resource cleanup and timeline disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    edges.dispose();
    edgeMaterial.dispose();
    imageTexture.dispose();
    depthTexture.dispose();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMaterial);
  };

  return group;
}
